package dev.pocketengine.features.local.project;
import static org.junit.Assert.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.json.*;import org.junit.*;
public final class ProjectFileMoveTest {
 private Path root;private static final String ID="11111111-1111-1111-1111-111111111111";private static final byte[] RAW={0,1,(byte)255,3};
 @Before public void create()throws Exception{root=Files.createTempDirectory("pw-real-move-");Files.write(root.resolve("from.bin"),RAW);Files.createDirectory(root.resolve("dest"));}
 @After public void close()throws Exception{try(var all=Files.walk(root)){for(Path p:all.sorted(Comparator.reverseOrder()).toArray(Path[]::new))Files.deleteIfExists(p);}}
 private JSONObject snapshot(Map<String,byte[]> data)throws Exception{JSONArray files=new JSONArray();for(var f:data.entrySet())files.put(new JSONObject().put("path",f.getKey()).put("binary",true).put("contentBase64",Base64.getEncoder().encodeToString(f.getValue())));return new JSONObject().put("checkout",new JSONObject().put("id",ID).put("projectId","22222222-2222-2222-2222-222222222222")).put("files",files);}
 private JSONObject edit()throws Exception{return new JSONObject().put("action","move").put("fromPath","from.bin").put("path","dest/to.bin").put("expectedHash","absent").put("expectedSourceHash",ProjectSources.sha256(RAW));}
 private JSONArray pair()throws Exception{return ProjectExactPatch.prepare(snapshot(Map.of("from.bin",RAW)),new JSONArray().put(edit()));}
 @Test public void pairedRowsFreezeOneExactSourceButPerformARealRenameAndConditionalRenameBack()throws Exception{JSONArray rows=pair();assertEquals(2,rows.length());assertArrayEquals(RAW,ProjectExactPatch.payloadBytes(rows.getJSONObject(0),true));assertArrayEquals(RAW,ProjectExactPatch.payloadBytes(rows.getJSONObject(1),false));JSONObject actual=ProjectFileMove.execute(root.toFile(),ID,rows,()->{});assertEquals(actual.toString(),"completed",actual.getString("status"));assertFalse(Files.exists(root.resolve("from.bin")));assertArrayEquals(RAW,Files.readAllBytes(root.resolve("dest/to.bin")));assertFalse(actual.getBoolean("crossFileAtomic"));JSONArray back=ProjectExactPatch.reverse(snapshot(Map.of("dest/to.bin",RAW)),rows,actual,UUID.randomUUID().toString());JSONObject restored=ProjectFileMove.execute(root.toFile(),ID,back,()->{});assertEquals("completed",restored.getString("status"));assertArrayEquals(RAW,Files.readAllBytes(root.resolve("from.bin")));assertFalse(Files.exists(root.resolve("dest/to.bin")));}
 @Test public void mixedActionsOverwritesWrongSourceAndForgedRowsCannotBecomeAPlainBinaryWriter()throws Exception{assertThrows(Exception.class,()->ProjectExactPatch.prepare(snapshot(Map.of("from.bin",RAW)),new JSONArray().put(edit()).put(new JSONObject().put("action","create").put("path","other").put("expectedHash","absent").put("content","x"))));assertThrows(Exception.class,()->ProjectFileMove.prepare(snapshot(Map.of("from.bin",RAW)),edit().put("contentBase64","AAAA")));assertThrows(Exception.class,()->ProjectFileMove.prepare(snapshot(Map.of("from.bin",RAW,"dest/to.bin",RAW)),edit()));assertThrows(SecurityException.class,()->ProjectFileMove.prepare(snapshot(Map.of("from.bin",RAW)),edit().put("expectedSourceHash","0".repeat(64))));JSONArray forged=pair();forged.getJSONObject(1).getJSONObject("move").put("toPath","different");assertThrows(SecurityException.class,()->ProjectFileMove.pair(forged));assertThrows(SecurityException.class,()->ProjectFileMove.pair(new JSONArray().put(pair().getJSONObject(0))));}
 @Test public void existingTargetsAndMissingParentsAreRejectedWithoutAPathEffect()throws Exception{JSONArray rows=pair();Files.write(root.resolve("dest/to.bin"),new byte[]{9});JSONObject failed=ProjectFileMove.execute(root.toFile(),ID,rows,()->{});assertEquals("failed",failed.getString("status"));assertFalse(failed.getBoolean("fileCommitAttempted"));assertArrayEquals(RAW,Files.readAllBytes(root.resolve("from.bin")));assertArrayEquals(new byte[]{9},Files.readAllBytes(root.resolve("dest/to.bin")));JSONArray missing=ProjectFileMove.prepare(snapshot(Map.of("from.bin",RAW)),edit().put("path","missing/to.bin"));assertEquals("failed",ProjectFileMove.execute(root.toFile(),ID,missing,()->{}).getString("status"));assertFalse(Files.exists(root.resolve("missing")));}
 @Test public void collisionAfterAdmissionKeepsUnknownRatherThanInventingANotDispatchedReceipt()throws Exception{JSONArray rows=pair();AtomicInteger before=new AtomicInteger();ProjectFileMove.preflight(root.toFile(),ID,rows,before::incrementAndGet);AtomicInteger calls=new AtomicInteger();JSONObject unknown=ProjectFileMove.execute(root.toFile(),ID,rows,()->{if(calls.incrementAndGet()==before.get()+1)Files.write(root.resolve("dest/to.bin"),new byte[]{9});});assertEquals(unknown.toString(),"unknown",unknown.getString("status"));assertFalse(unknown.getBoolean("receiptReceived"));assertTrue(unknown.getBoolean("fileCommitAttempted"));assertArrayEquals(RAW,Files.readAllBytes(root.resolve("from.bin")));assertArrayEquals(new byte[]{9},Files.readAllBytes(root.resolve("dest/to.bin")));assertThrows(SecurityException.class,()->ProjectExactPatch.reverse(snapshot(Map.of("from.bin",RAW,"dest/to.bin",new byte[]{9})),rows,unknown,UUID.randomUUID().toString()));}
 @Test public void cancellationBeforeRenameAndChangedAfterStateCannotBecomeAReversal()throws Exception{JSONArray rows=pair();JSONObject failed=ProjectFileMove.execute(root.toFile(),ID,rows,()->{throw new InterruptedException("original cancelled");});assertFalse(failed.getBoolean("fileCommitAttempted"));JSONObject actual=ProjectFileMove.execute(root.toFile(),ID,rows,()->{});assertThrows(SecurityException.class,()->ProjectExactPatch.reverse(snapshot(Map.of("dest/to.bin",new byte[]{9})),rows,actual,UUID.randomUUID().toString()));assertThrows(SecurityException.class,()->ProjectExactPatch.reverse(snapshot(Map.of("dest/to.bin",RAW,"from.bin",new byte[]{8})),rows,actual,UUID.randomUUID().toString()));}
}
